import 'server-only';
import ru from '@/content/data.ru.json';
import tg from '@/content/data.tg.json';
import en from '@/content/data.en.json';
import { pricing } from '@/content/pricing';
import { getPublicConfig } from './config';
import type { SiteData } from './types';

const DATA = { ru, tg, en } as unknown as Record<string, SiteData>;

/**
 * Project data for a locale. Today: static JSON generated by tools/i18n/build-data.mjs
 * plus owner settings from the environment. Later: the CMS.
 */
export function getSiteData(locale: string) {
  return { d: DATA[locale] ?? DATA.ru, pricing, cfg: getPublicConfig(), demo: pricing.isDemo };
}
